71: async function writeWizardConfigFile(
72:   configInput: OpenClawConfig,
73:   opts: {
74:     allowConfigSizeDrop?: boolean;
75:     migrationBaseConfig?: OpenClawConfig;
76:     onPendingPluginInstallMigration?: () => void;
77:   } = {},
78: ): Promise<OpenClawConfig> {
79:   let config = configInput;
80:   const allowConfigSizeDrop = opts.allowConfigSizeDrop === true;
81:   if (!allowConfigSizeDrop && hasPendingPluginInstallRecords(config)) {
82:     const migrationBaseConfig = opts.migrationBaseConfig;
83:     if (migrationBaseConfig && hasPendingPluginInstallRecords(migrationBaseConfig)) {
84:       await commitConfigWriteWithPendingPluginInstalls({
85:         nextConfig: migrationBaseConfig,
86:         writeOptions: { allowConfigSizeDrop: true },
87:         commit: async (nextConfig, writeOptions) => {
88:           return await replaceConfigFile({
89:             nextConfig,
90:             ...(writeOptions ? { writeOptions } : {}),
91:             afterWrite: { mode: "auto" },
92:           });
93:         },
94:       });
95:       config = stripPendingPluginInstallRecords(
96:         config,
97:         unchangedPendingPluginInstallRecordIds(config, migrationBaseConfig),
98:       );
99:       opts.onPendingPluginInstallMigration?.();
100:     }
101:   }
102:   const committed = await commitConfigWriteWithPendingPluginInstalls({
103:     nextConfig: config,
104:     writeOptions: { allowConfigSizeDrop },
105:     commit: async (nextConfig, writeOptions) => {
106:       return await replaceConfigFile({
107:         nextConfig,
108:         ...(writeOptions ? { writeOptions } : {}),
109:         afterWrite: { mode: "auto" },
110:       });
111:     },
112:   });
113:   return committed.config;
114: }
