143:   const [{ resolveManifestProviderAuthChoice }, { resolvePluginSetupProvider }] = await Promise.all(
144:     [import("../plugins/provider-auth-choices.js"), import("../plugins/setup-registry.js")],
145:   );
146:   const manifestChoice = resolveManifestProviderAuthChoice(params.authChoice, {
147:     config: params.config,
148:     workspaceDir: params.workspaceDir,
149:     env: params.env,
150:     includeUntrustedWorkspacePlugins: false,
151:   });
152:   if (manifestChoice) {
153:     const setupProvider = resolvePluginSetupProvider({
154:       provider: manifestChoice.providerId,
155:       config: params.config,
156:       workspaceDir: params.workspaceDir,
157:       env: params.env,
158:       pluginIds: [manifestChoice.pluginId],
159:     });
160:     const setupMethod = setupProvider?.auth.find(
161:       (method) => normalizeProviderId(method.id) === normalizeProviderId(manifestChoice.methodId),
162:     );
163:     const setupPolicy =
164:       setupMethod?.wizard?.modelSelection ?? setupProvider?.wizard?.setup?.modelSelection;
165:     return {
166:       preferredProvider,
167:       promptWhenAuthChoiceProvided: setupPolicy?.promptWhenAuthChoiceProvided === true,
168:       allowKeepCurrent: setupPolicy?.allowKeepCurrent ?? true,
169:     };
170:   }
171: 
172:   const { resolvePluginProviders, resolveProviderPluginChoice } =
173:     await import("../plugins/provider-auth-choice.runtime.js");
174:   const providers = resolvePluginProviders({
175:     config: params.config,
176:     workspaceDir: params.workspaceDir,
177:     env: params.env,
178:     mode: "setup",
179:   });
180:   const resolvedChoice = resolveProviderPluginChoice({
181:     providers,
182:     choice: params.authChoice,
183:   });
184:   const matchedProvider =
185:     resolvedChoice?.provider ??
186:     (() => {
187:       const preferredId = preferredProvider?.trim();
188:       if (!preferredId) {
189:         return undefined;
190:       }
191:       return providers.find(
192:         (provider) => typeof provider.id === "string" && provider.id.trim() === preferredId,
193:       );
194:     })();
195:   const setupPolicy =
