3:   autocomplete,
4:   autocompleteMultiselect,
5:   cancel,
6:   confirm,
7:   intro,
8:   isCancel,
9:   multiselect,
10:   type Option,
11:   outro,
12:   password,
13:   select,
14:   spinner,
15:   text,
16: } from "@clack/prompts";
17: import { normalizeLowercaseStringOrEmpty } from "@openclaw/normalization-core/string-coerce";
18: import { stripAnsi } from "../../packages/terminal-core/src/ansi.js";
19: import { note as emitNote } from "../../packages/terminal-core/src/note.js";
20: import {
21:   stylePromptHint,
22:   stylePromptMessage,
23:   stylePromptTitle,
24: } from "../../packages/terminal-core/src/prompt-style.js";
