28: import { WizardCancelledError } from "./prompts.js";
29: 
30: // Clack-backed WizardPrompter implementation for interactive CLI setup. It
31: // converts the generic wizard prompt contract into styled Clack prompts.
32: function guardCancel<T>(value: T | symbol): T {
33:   if (isCancel(value)) {
34:     cancel(stylePromptTitle("Setup cancelled.") ?? "Setup cancelled.");
35:     throw new WizardCancelledError();
36:   }
37:   return value;
38: }
39: 
40: function normalizeSearchTokens(search: string): string[] {
41:   return normalizeLowercaseStringOrEmpty(search)
42:     .split(/\s+/)
43:     .map((token) => token.trim())
44:     .filter((token) => token.length > 0);
45: }
46: 
47: function buildOptionSearchText<T>(option: Option<T>): string {
48:   const label = stripAnsi(option.label ?? "");
49:   const hint = stripAnsi(option.hint ?? "");
50:   const value = String(option.value ?? "");
51:   return normalizeLowercaseStringOrEmpty(`${label} ${hint} ${value}`);
52: }
53: 
54: export function tokenizedOptionFilter<T>(search: string, option: Option<T>): boolean {
55:   const tokens = normalizeSearchTokens(search);
56:   if (tokens.length === 0) {
57:     return true;
58:   }
59:   const haystack = buildOptionSearchText(option);
60:   return tokens.every((token) => haystack.includes(token));
61: }
62: 
63: // Public factory used by setup/onboard commands. Keep side effects inside method
64: // calls so tests can import the module without starting prompts.
65: export function createClackPrompter(): WizardPrompter {
66:   return {
67:     intro: async (title) => {
68:       intro(stylePromptTitle(title) ?? title);
69:     },
70:     outro: async (message) => {
71:       outro(stylePromptTitle(message) ?? message);
72:     },
73:     note: async (message, title) => {
74:       emitNote(message, title);
75:     },
76:     plain: async (message) => {
77:       process.stdout.write(message.endsWith("\n") ? message : `${message}\n`);
78:     },
79:     select: async (params) => {
80:       const options = params.options.map((opt) => {
81:         const base = { value: opt.value, label: opt.label };
82:         return opt.hint === undefined ? base : { ...base, hint: stylePromptHint(opt.hint) };
83:       }) as Option<(typeof params.options)[number]["value"]>[];
84: 
85:       if (params.searchable) {
86:         return guardCancel(
87:           await autocomplete({
88:             message: stylePromptMessage(params.message),
89:             options,
90:             initialValue: params.initialValue,
91:             filter: tokenizedOptionFilter,
92:           }),
93:         );
94:       }
95: 
96:       return guardCancel(
97:         await select({
98:           message: stylePromptMessage(params.message),
99:           options,
100:           initialValue: params.initialValue,
101:         }),
102:       );
103:     },
104:     multiselect: async (params) => {
105:       const options = params.options.map((opt) => {
106:         const base = { value: opt.value, label: opt.label };
107:         return opt.hint === undefined ? base : { ...base, hint: stylePromptHint(opt.hint) };
108:       }) as Option<(typeof params.options)[number]["value"]>[];
109: 
110:       if (params.searchable) {
111:         return guardCancel(
112:           await autocompleteMultiselect({
113:             message: stylePromptMessage(params.message),
114:             options,
115:             initialValues: params.initialValues,
116:             filter: tokenizedOptionFilter,
117:           }),
118:         );
119:       }
120: 
121:       return guardCancel(
122:         await multiselect({
123:           message: stylePromptMessage(params.message),
124:           options,
125:           initialValues: params.initialValues,
126:         }),
127:       );
128:     },
